// Normalize WhatsApp Cloud API webhook payload with input guards.
const payload = $input.first().json;
const headers = payload.headers || {};
const businessPhone = ($env.WHATSAPP_BUSINESS_PHONE || '').replace(/\D/g, '');
for (const entry of payload.body.entry || payload.entry || []) {
  for (const change of entry.changes || []) {
    const value = change.value || {};
    if (value.messages && value.messages.length > 0) {
      const msg = value.messages[0];
      const from = String(msg.from || '').replace(/\D/g, '');
      // Loop prevention: ignore messages sent by the business's own number.
      if (businessPhone && from === businessPhone) {
        return [{ json: { valid: false, reason: 'own_number' } }];
      }
      const isText = msg.type === 'text' && msg.text && msg.text.body;
      if (!isText) {
        return [{ json: { valid: false, reason: 'unsupported_type' } }];
      }
      return [{ json: {
        valid: true,
        reason: 'text',
        contact_phone: from,
        message_text: String(msg.text.body).slice(0, 2000),
        message_id: msg.id || '',
        timestamp: msg.timestamp || '',
        type: msg.type
      }}];
    }
    if (value.statuses && value.statuses.length > 0) {
      return [{ json: { valid: false, reason: 'status' } }];
    }
  }
}
return [{ json: { valid: false, reason: 'no_message' } }];

// Historial seguro (try/catch + normalizacion) + mensaje nuevo.
let historyRows = [];
try { historyRows = $('Obtener Historial').all().map(i => i.json).flat(1).filter(r => r && typeof r === 'object' && !Array.isArray(r)); } catch (e) {}
const contents = historyRows.map(h => ({ role: h.role === 'assistant' ? 'model' : 'user', parts: [{ text: h.content }] }));
contents.push({ role: 'user', parts: [{ text: $('Normalizar Mensaje').item.json.message_text }] });
const systemInstruction = $env.SYSTEM_PROMPT || 'Eres el asistente virtual del negocio. Responde corto y claro.';
return [{ json: { model: 'gemini-2.5-flash', contents, system_instruction: { parts: [{ text: systemInstruction }] } } }];

// Extract text from Gemini response and clean control markers
const text = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts[0].text) || '';
const clean = text.replace(/\[DERIVAR\]/gi, '').replace(/\[LEAD[^\]]*\]/gi, '').trim().slice(0, 4000);
return [{ json: { raw: text, clean, needs_human: /\[DERIVAR\]/i.test(text), lead_marker: (text.match(/\[LEAD ([^\]]*)\]/i) || [null, ''])[1] } }];

// Verify Meta webhook signature (X-Hub-Signature-256) with the app secret.
// Dev (WEBHOOK_VERIFY_SIGNATURE=false): pasa sin verificar (modo disabled).
// Produccion: HMAC-SHA256 via WebCrypto (sin require, compatible con el sandbox de n8n).
const mode = String($env.WEBHOOK_VERIFY_SIGNATURE || 'false').toLowerCase();
const passthrough = (verified, m) => [{ json: Object.assign({ verified, mode: m }, $input.first().json) }];

if (mode === 'false') {
  return passthrough(true, 'disabled');
}

const secret = $env.META_APP_SECRET || '';
const headers = $input.first().json.headers || {};
const signature = headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '';
const rawBody = JSON.stringify($input.first().json.body);

if (!secret) {
  return passthrough(false, 'missing_secret');
}

const run = async () => {
  try {
    const encoder = new TextEncoder();
    const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const sig = await crypto.subtle.sign('HMAC', key, encoder.encode(rawBody));
    const hex = Array.from(new Uint8Array(sig)).map(b => b.toString(16).padStart(2, '0')).join('');
    return passthrough(signature === 'sha256=' + hex, 'enabled');
  } catch (e) {
    return passthrough(false, 'crypto_unavailable');
  }
};
return run();

// Normaliza el resultado de Obtener Contacto (items-fila o 1 item-array) y emite SIEMPRE 1 item.
const raw = $('Obtener Contacto').all().map(i => i.json);
const rows = raw.flat(1).filter(r => r && typeof r === 'object' && !Array.isArray(r));
const telefono = $('Normalizar Mensaje').item.json.contact_phone || '';
return [{ json: { exists: rows.length > 0, contacto: rows[0] || null, telefono } }];

// Unifica el contacto existente o el recien creado; try/catch porque los nodos pueden no haberse ejecutado.
let fromEval = {};
try { fromEval = $('Evaluar Contacto').all().map(i => i.json)[0] || {}; } catch (e) {}
let fromCreate = {};
try { fromCreate = $('Crear Contacto').all().map(i => i.json)[0] || {}; } catch (e) {}
const c = (fromEval.contacto && fromEval.contacto.id ? fromEval.contacto : fromCreate) || {};
return [{ json: { contacto_id: c.id || null, tenant_id: c.tenant_id || null, telefono: fromEval.telefono || '' } }];
